        val createDatabase = findViewById<Button>(R.id.createDatabase)
        // 初始化数据库帮助类，参数依次为上下文、数据库名、版本号
        val dbHelper = MyDatabaseHelper(this, "BookStore.db", 2)

        // 设置创建数据库按钮的点击事件监听器
        createDatabase.setOnClickListener {
            // 获取可写的数据库实例，确保数据库和表被创建
            dbHelper.writableDatabase
        }

        // 获取添加数据按钮实例
        val addDate = findViewById<Button>(R.id.addData)
        // 设置添加数据按钮的点击事件监听器
        addDate.setOnClickListener {
            // 获取可写的数据库实例
            val db = dbHelper.writableDatabase

            // 准备要插入的数据1
            val values1 = ContentValues().apply {
                put("name", "The Da Vinci Code")
                put("author", "Dan Brown")
                put("pages", 454)
                put("price", 16.96)
            }
            // 将数据插入到"Book"表中，返回新行的ID
            db.insert("Book", null, values1)

            // 准备要插入的数据2
            val values2 = ContentValues().apply {
                put("name", "The Lost Symbol")
                put("author", "Dan Brown")
                put("pages", 510)
                put("price", 19.95)
            }
            // 将数据插入到"Book"表中，返回新行的ID
            db.insert("Book", null, values2)
        }

        // 获取更新数据按钮实例
        val updateData = findViewById<Button>(R.id.updateData)
        // 设置更新数据按钮的点击事件监听器
        updateData.setOnClickListener {
            // 获取可写的数据库实例
            val db = dbHelper.writableDatabase

            // 准备要更新的数据
            val values = ContentValues()
            values.put("price", 10.99)

            // 更新"Book"表中满足条件的记录
            // 条件：name等于"The Da Vinci Code"
            db.update("Book", values, "name = ?", arrayOf("The Da Vinci Code"))
        }

        // 获取删除数据按钮实例
        val deleteData = findViewById<Button>(R.id.deleteData)
        // 设置删除数据按钮的点击事件监听器
        deleteData.setOnClickListener {
            // 获取可写的数据库实例
            val db = dbHelper.writableDatabase

            // 删除"Book"表中满足条件的记录
            // 条件：pages大于500
            db.delete("Book", "pages > ?", arrayOf("500"))
        }

        // 获取查询数据按钮实例
        val queryData = findViewById<Button>(R.id.queryData)
        // 设置查询数据按钮的点击事件监听器
        queryData.setOnClickListener {
            // 获取可写的数据库实例
            val db = dbHelper.writableDatabase

            // 查询"Book"表中的所有数据
            val cursor = db.query("Book", null, null, null, null, null, null)

            // 遍历查询结果
            if (cursor.moveToFirst()) {
                do {
                    // 获取每一列的数据
                    val name = cursor.getString(cursor.getColumnIndex("name"))
                    val author = cursor.getString(cursor.getColumnIndex("author"))
                    val pages = cursor.getInt(cursor.getColumnIndex("pages"))
                    val price = cursor.getDouble(cursor.getColumnIndex("price"))

                    // 打印日志，显示查询到的数据
                    println("name is $name, author is $author, pages is $pages, price is $price")
                } while (cursor.moveToNext())
            }

            // 关闭游标，释放资源
            cursor.close()
        }

        // 获取替换数据按钮实例
        val replaceData = findViewById<Button>(R.id.replaceData)
        // 设置替换数据按钮的点击事件监听器
        replaceData.setOnClickListener {
            // 获取可写的数据库实例
            val db = dbHelper.writableDatabase

            // 开始一个事务
            db.beginTransaction()
            try {
                // 删除"Book"表中的所有记录
                db.delete("Book", null, null)

                // 这里可以手动抛出异常进行事务回滚测试
                // if (true) {
                //     throw NullPointerException()
                // }

                // 准备要插入的数据
                val values = ContentValues().apply {
                    put("name", "Game of Thrones")
                    put("author", "George Martin")
                    put("pages", 720)
                    put("price", 20.85)
                }

                // 将数据插入到"Book"表中
                db.insert("Book", null, values)

                // 标记事务为成功
                db.setTransactionSuccessful()
            } catch (e: Exception) {
                // 捕获异常并打印异常信息
                e.printStackTrace()
            } finally {
                // 结束事务
                db.endTransaction()
            }
        }
    }
}

