### 从相册中选择图片

1.申请权限

2.创建并调用openAlum()方法

3.重写onActivityResult处理结果

4.针对不同图片格式进行不同操作

```java
/**
 * 主活动类，实现了拍照和从相册选择图片的功能
 */
public class MainActivity extends AppCompatActivity {

    // 日志标签，用于日志输出
    public static final String TAG = "MainActivity";

    // 请求拍照的常量
    public static final int TAKE_PHOTO = 1;

    // 权限请求码
    public static final int REQUEST_PERMISSION = 2;

    // 从相册选择图片的请求码
    public static final int CHOOSE_PHOTO = 3;

    // 用于显示图片的ImageView
    private ImageView picture;

    // 用于保存图片的Uri
    private Uri imageUri;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        // 加载布局文件
        setContentView(R.layout.activity_main);

        // 获取控件实例
        Button takePhoto = findViewById(R.id.take_photo);
        Button chooseFromAlbum = findViewById(R.id.choose_from_album);
        picture = findViewById(R.id.picture);

        // 设置从相册选择图片按钮的点击事件监听器
        chooseFromAlbum.setOnClickListener(v -> {
            // 检查存储读取权限
            if (ContextCompat.checkSelfPermission(MainActivity.this, Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
                // 如果没有权限，请求权限
                ActivityCompat.requestPermissions(MainActivity.this, new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE}, 1);
            } else {
                // 如果有权限，打开相册
                openAlbum();
            }
        });
    }

    /**
     * 打开相册，选择图片
     */
    private void openAlbum() {
        Intent intent = new Intent("android.intent.action.GET_CONTENT");
        // 设置类型为图片
        intent.setType("image/*");
        // 启动相册并等待结果
        startActivityForResult(intent, CHOOSE_PHOTO);
    }

    /**
     * 处理拍照和选择图片的结果
     * @param requestCode 请求码，用于区分不同的操作
     * @param resultCode 结果码，表示操作的结果
     * @param data 返回的数据，包含图片信息
     */
    @SuppressLint("MissingSuperCall")
    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        // 确保返回的是拍照结果
        if (requestCode == TAKE_PHOTO) {
            // 如果拍照成功
            if (resultCode == RESULT_OK) {
                try {
                    // 使用 BitmapFactory.Options 缩放图片，避免内存溢出
                    BitmapFactory.Options options = new BitmapFactory.Options();
                    options.inSampleSize = 4; // 设置缩放比例，减少内存消耗
                    // 从Uri中获取图片并转换为Bitmap
                    Bitmap bitmap = BitmapFactory.decodeStream(getContentResolver().openInputStream(imageUri), null, options);
                    // 设置Bitmap到ImageView中显示
                    picture.setImageBitmap(bitmap);
                } catch (FileNotFoundException e) {
                    // 捕获文件未找到异常
                    e.printStackTrace();
                }
            }
        } else if (requestCode == CHOOSE_PHOTO) {
            // 如果是从相册选择图片的结果
            if (resultCode == RESULT_OK) {
                // 根据Android版本处理图片
                if (Build.VERSION.SDK_INT >= 19) {
                    handleImageOnKitKat(data);
                } else {
                    handleImageBeforeKitKat(data);
                }
            }
        }
    }

    /**
     * 处理权限请求的结果
     * @param requestCode 请求码
     * @param permissions 请求的权限数组
     * @param grantResults 权限授予结果数组
     */
    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        // 如果请求的是相机权限
        if (requestCode == REQUEST_PERMISSION) {
            // 判断权限是否被授予
            if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                // 权限授予，提示用户
                Toast.makeText(this, "相机权限已授予", Toast.LENGTH_SHORT).show();
            } else {
                // 权限被拒绝，提示用户
                Toast.makeText(this, "相机权限被拒绝", Toast.LENGTH_SHORT).show();
            }
        } else if (requestCode == 1) {
            // 如果请求的是存储权限
            if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                // 权限授予，打开相册
                openAlbum();
            } else {
                // 权限被拒绝，提示用户
                Toast.makeText(this, "存储权限被拒绝，无法打开相册", Toast.LENGTH_SHORT).show();
            }
        }
    }

    /**
     * 处理Android 4.4及以上版本的图片选择结果
     * @param data 包含图片信息的Intent
     */
    @TargetApi(19)
    private void handleImageOnKitKat(Intent data) {
        String imagePath = null;
        Uri uri = data.getData();
        if (DocumentsContract.isDocumentUri(this, uri)) {
            String docId = DocumentsContract.getDocumentId(uri);
            if ("com.android.providers.media.documents".equals(uri.getAuthority())) {
                // 处理媒体库中的图片
                String id = docId.split(":")[1];
                String selection = MediaStore.Images.Media._ID + "=" + id;
                imagePath = getImagePath(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, selection);
            } else if ("com.android.providers.downloads.documents".equals(uri.getAuthority())) {
                // 处理下载目录中的图片
                Uri contentUri = ContentUris.withAppendedId(Uri.parse("content://downloads/public_downloads"), Long.valueOf(docId));
                imagePath = getImagePath(contentUri, null);
            }
        } else if ("content".equalsIgnoreCase(uri.getScheme())) {
            // 处理内容提供者中的图片
            imagePath = getImagePath(uri, null);
        } else if ("file".equalsIgnoreCase(uri.getScheme())) {
            // 处理文件路径中的图片
            imagePath = uri.getPath();
        }
        displayImage(imagePath);
    }

    /**
     * 处理Android 4.4以下版本的图片选择结果
     * @param data 包含图片信息的Intent
     */
    private void handleImageBeforeKitKat(Intent data) {
        Uri uri = data.getData();
        String imagePath = getImagePath(uri, null);
        displayImage(imagePath);
    }

    /**
     * 获取图片路径
     * @param uri 图片的Uri
     * @param selection 查询条件
     * @return 图片路径
     */
    @SuppressLint("Range")
    private String getImagePath(Uri uri, String selection) {
        String path = null;
        Cursor cursor = getContentResolver().query(uri, null, selection, null, null);
        if (cursor != null) {
            if (cursor.moveToFirst()) {
                path = cursor.getString(cursor.getColumnIndex(MediaStore.Images.Media.DATA));
            }
            cursor.close();
        }
        return path;
    }

    /**
     * 显示图片
     * @param imagePath 图片路径
     */
    private void displayImage(String imagePath) {
        if (imagePath != null) {
            // 将图片文件解码为Bitmap
            Bitmap bitmap = BitmapFactory.decodeFile(imagePath);
            // 显示Bitmap到ImageView中
            picture.setImageBitmap(bitmap);
        } else {
            Toast.makeText(this, "failed to get image", Toast.LENGTH_SHORT).show();
        }
    }
}
