/**
 * MainActivity类，负责控制音频播放。
 */
public class MainActivity extends AppCompatActivity implements View.OnClickListener {

    // MediaPlayer对象，用于播放音频。
    private MediaPlayer mediaPlayer = new MediaPlayer();

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // 获取控件。
        Button play = (Button) findViewById(R.id.play);
        Button pause = (Button) findViewById(R.id.pause);
        Button stop = (Button) findViewById(R.id.stop);

        // 为控件设置点击监听器。
        play.setOnClickListener(this);
        pause.setOnClickListener(this);
        stop.setOnClickListener(this);

        // 检查是否有写外部存储权限，如果没有，则请求权限。
        if (ContextCompat.checkSelfPermission(MainActivity.this, Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
            ActivityCompat.requestPermissions(MainActivity.this, new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE}, 1);
        } else {
            // 如果有权限，则初始化MediaPlayer。
            initMediaPlayer();
        }
    }

    /**
     * 初始化MediaPlayer，设置音频文件路径和准备播放。
     */
    private void initMediaPlayer() {
        try {
            // 获取外部存储目录下的音频文件。
            File file = new File(Environment.getExternalStorageDirectory(), "music.mp3");
            // 设置音频文件路径。
            mediaPlayer.setDataSource(file.getPath());
            // 准备播放。
            mediaPlayer.prepare();
        } catch (Exception e) {
            // 如果发生异常，则打印异常信息。
            e.printStackTrace();
        }
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults);
        switch (requestCode) {
            case 1:
                // 如果用户同意了权限请求，则初始化MediaPlayer。
                if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                    initMediaPlayer();
                } else {
                    // 如果用户拒绝了权限请求，则提示用户无法使用程序。
                    Toast.makeText(this, "拒绝权限将无法使用程序", Toast.LENGTH_SHORT).show();
                    finish();
                }
                break;
            default:
        }
    }

    @Override
    public void onClick(View v) {
        // 根据点击的控件ID执行相应的操作。
        if (v.getId() == R.id.play) {
            // 如果点击的是播放按钮，则开始播放音频。
            if (!mediaPlayer.isPlaying()) {
                mediaPlayer.start();
            }
        } else if (v.getId() == R.id.pause) {
            // 如果点击的是暂停按钮，则暂停播放音频。
            if (mediaPlayer.isPlaying()) {
                mediaPlayer.pause();
            }
        } else if (v.getId() == R.id.stop) {
            // 如果点击的是停止按钮，则停止播放音频并重新初始化MediaPlayer。
            if (mediaPlayer.isPlaying()) {
                mediaPlayer.reset();
                initMediaPlayer();
            }
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        // 在程序销毁时释放MediaPlayer资源。
        if (mediaPlayer != null) {
            mediaPlayer.release();
        }
    }
}
