                if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                    // 如果权限授予，初始化视频路径
                    initVideoPath();
                } else {
                    // 如果权限拒绝，显示提示并结束活动
                    Toast.makeText(this, "拒绝权限将无法使用程序", Toast.LENGTH_SHORT).show();
                    finish();
                }
                break;
            default:
                // 处理其他请求码
        }
    }

    /**
     * 处理按钮点击事件
     * @param v 被点击的视图
     */
    @Override
    public void onClick(View v) {
        if (v.getId() == R.id.play) {
            // 播放按钮点击事件
            if (!videoView.isPlaying()) {
                // 如果没有在播放，开始播放
                videoView.start();
            }
        } else if (v.getId() == R.id.pause) {
            // 暂停按钮点击事件
            if (videoView.isPlaying()) {
                // 如果正在播放，暂停播放
                videoView.pause();
            }
        } else if (v.getId() == R.id.replay) {
            // 重新播放按钮点击事件
            if (videoView.isPlaying()) {
                // 如果正在播放，恢复播放
                videoView.resume();
            }
        }
    }

    /**
     * 活动销毁时的回调
     * 释放资源，避免内存泄漏
     */
    @Override
    protected void onDestroy() {
        super.onDestroy();
        if (videoView != null) {
            // 停止视频播放并释放资源
            videoView.suspend();
        }
    }
}
