## 运用HTTP协议访问网络

### 使用HttpURLConnection

1.调用sendRequestWithHttpURLConnection()方法开启子线程,并使用HttpURLConnection发出HTTP请求

2.利用BufferedReader对服务器返回的流进行读取,并将结果传到showResponse方法中

3.在showResponse里通过runOnUiThread将线程切换到主线程,然后更新UI元素

```java
/**
 * 主活动类，展示如何通过HttpURLConnection发送网络请求
 */
public class MainActivity extends AppCompatActivity implements View.OnClickListener {

    TextView responseText; // 用于显示服务器响应的文本视图

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        // 设置内容视图
        setContentView(R.layout.activity_main);

        // 初始化按钮和文本视图
        Button sendRequest = findViewById(R.id.send_request);
        responseText = findViewById(R.id.response_text);

        // 设置按钮的点击监听器
        sendRequest.setOnClickListener(this);
    }

    @Override
    public void onClick(View v) {
        // 判断是否是发送请求按钮的点击事件
        if (v.getId() == R.id.send_request) {
            // 调用发送请求的方法
            sendRequestWithHttpURLConnection();    
        }
    }

    /**
     * 使用HttpURLConnection发送网络请求
     * 在子线程中执行网络操作，避免阻塞主线程
     */
    private void sendRequestWithHttpURLConnection() {
        new Thread(new Runnable() {
            @Override
            public void run() {
                HttpURLConnection connection = null;
                BufferedReader reader = null;
                InputStream in = null;
                try {
                    // 创建URL对象
                    URL url = new URL("https://www.baidu.com");
                    // 打开HTTP连接
                    connection = (HttpURLConnection) url.openConnection();
                    // 设置请求方法为GET

                    /*
                    GET:从服务器获取数据
                    POST:提交数据给服务器
                    */

                    connection.setRequestMethod("GET");
                    // 设置连接超时时间（单位：毫秒）
                    connection.setConnectTimeout(8000);
                    // 设置读取超时时间（单位：毫秒）
                    connection.setReadTimeout(8000);

                    // 获取输入流，读取服务器响应内容
                    in = connection.getInputStream();
                    reader = new BufferedReader(new InputStreamReader(in));

                    // 读取响应内容
                    StringBuilder response = new StringBuilder();
                    String line;
                    while ((line = reader.readLine()) != null) {
                        response.append(line);
                    }

                    // 更新UI显示响应内容
                    showResponse(response.toString());

                } catch (MalformedURLException e) {
                    // URL格式错误异常
                    e.printStackTrace();
                } catch (IOException e) {
                    // 网络IO异常
                    e.printStackTrace();
                } finally {
                    // 确保释放资源
                    try {
                        if (reader != null) {
                            reader.close();
                        }
                        if (in != null) {
                            in.close();
                        }
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                    if (connection != null) {
                        connection.disconnect();
                    }
                }
            }
        }).start();
    }

    /**
     * 在主线程中更新UI，显示服务器响应内容
     * @param response 服务器响应的内容
     */
    private void showResponse(final String response) {
        runOnUiThread(new Runnable() {
            @Override
            public void run() {
                // 更新文本视图显示响应内容
                responseText.setText(response);
            }
        });
    }
}
```

