    // 日志标签，用于输出日志信息
    public static final String TAG = "Myservice";

    /**
     * DownloadBinder是一个Binder内部类，提供了服务的接口方法。
     * 通过该Binder，活动可以调用服务的方法。
     */
    class DownloadBinder extends Binder {
        /**
         * 开始下载的方法。
         * 当前仅输出日志信息，具体下载逻辑需在此实现。
         */
