```java
public class DownloadTask extends AsyncTask<String, Integer, Integer> {

    /**
     * 下载状态：成功
     */
    public static final int TYPE_SUCCESS = 0;
    /**
     * 下载状态：失败
     */
    public static final int TYPE_FAILED = 1;
    /**
     * 下载状态：暂停
     */
    public static final int TYPE_PAUSED = 2;
    /**
     * 下载状态：取消
     */
    public static final int TYPE_CANCELED = 3;

    /**
     * 下载事件监听器，用于接收下载状态和进度更新
     */
    private DownloadListener listener;

    /**
     * 标记下载是否被取消
     */
    private boolean isCanceled = false;

    /**
     * 标记下载是否被暂停
     */
    private boolean isPaused = false;

    /**
     * 记录最后一次上传的进度值，避免重复更新
     */
    private int lastProgress;

    /**
     * 构造函数，初始化下载监听器
     *
     * @param listener 下载事件的回调接口
     */
    public DownloadTask(DownloadListener listener) {
        this.listener = listener;
    }

    /**
     * 后台执行下载任务的主方法
     *
     * @param params 参数数组，第一个元素为下载 URL
     * @return 下载状态，取值为 TYPE_SUCCESS、TYPE_FAILED、TYPE_PAUSED、TYPE_CANCELED
     */
    @Override
    protected Integer doInBackground(String... params) {
        InputStream is = null;
        RandomAccessFile savedFile = null;
        File file = null;
        try {
            long downloadedLength = 0;

            // 获取下载 URL 和文件名
            String downloadUrl = params[0];
            String fileName = downloadUrl.substring(downloadUrl.lastIndexOf("/"));

            // 设置下载目录为公共下载目录
            String directory = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS).getPath();
            file = new File(directory + fileName);

            // 如果文件已存在，记录已下载的长度
            if (file.exists()) {
                downloadedLength = file.length();
            }

            // 获取文件总长度
            long contentLength = getContentLength(downloadUrl);
            if (contentLength == 0) {
                return TYPE_FAILED;
            } else if (contentLength == downloadedLength) {
                return TYPE_SUCCESS;
            }

            // 发送带有 Range 头的请求，继续断点下载
            OkHttpClient client = new OkHttpClient();
            Request request = new Request.Builder()
                    .addHeader("RANGE", "bytes=" + downloadedLength + "-")
                    .url(downloadUrl)
                    .build();
            Response response = client.newCall(request).execute();

            if (response != null) {
                is = response.body().byteStream();
                savedFile = new RandomAccessFile(file, "rw");
                savedFile.seek(downloadedLength);

                byte[] b = new byte[1024];
                int total = 0;
                int len;
                while ((len = is.read(b)) != -1) {
                    if (isCanceled) {
                        return TYPE_CANCELED;
                    } else if (isPaused) {
                        return TYPE_PAUSED;
                    } else {
                        total += len;
                        savedFile.write(b, 0, len);

                        // 计算并发布进度
                        int progress = (int) ((total + downloadedLength) * 100 / contentLength);
                        publishProgress(progress);
                    }
                }

                response.body().close();
                return TYPE_SUCCESS;
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                // 释放资源
                if (is != null) {
                    is.close();
                }
                if (savedFile != null) {
                    savedFile.close();
                }
                // 如果下载被取消，删除已下载的文件
                if (isCanceled && file != null) {
                    file.delete();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return TYPE_FAILED;
    }

    /**
     * 在主线程更新下载进度
     *
     * @param values 进度数组，第一个元素为当前进度
     */
    @Override
    protected void onProgressUpdate(Integer... values) {
        int progress = values[0];
        if (progress > lastProgress) {
            listener.onProgress(progress);
            lastProgress = progress;
        }
    }

    /**
     * 在主线程执行下载完成后的处理
     *
     * @param status 下载状态，取值为 TYPE_SUCCESS、TYPE_FAILED、TYPE_PAUSED、TYPE_CANCELED
     */
    @Override
    protected void onPostExecute(Integer status) {
        switch (status) {
            case TYPE_SUCCESS:
                listener.onSuccess();
                break;
            case TYPE_FAILED:
                listener.onFailed();
                break;
            case TYPE_PAUSED:
                listener.onPaused();
                break;
            case TYPE_CANCELED:
                listener.onCanceled();
                break;
            default:
                break;
        }
    }

    /**
     * 暂停下载
     */
    public void pauseDownload() {
        isPaused = true;
    }

    /**
     * 取消下载
     */
    public void cancelDownload() {
        isCanceled = true;
    }

    /**
     * 获取下载文件的总长度
     *
     * @param downloadUrl 下载 URL
     * @return 文件总长度
     * @throws IOException 网络请求异常
     */
    private long getContentLength(String downloadUrl) throws IOException {
        OkHttpClient client = new OkHttpClient();
        Request request = new Request.Builder()
                .url(downloadUrl)
                .build();
        Response response = client.newCall(request).execute();
        if (response != null && response.isSuccessful()) {
            long contentLength = response.body().contentLength();
            response.body().close();
            return contentLength;
        }
        return 0;
    }
}
