// 主活动类，继承自AppCompatActivity，并实现了View.OnClickListener接口
public class MainActivity extends AppCompatActivity implements View.OnClickListener {

    // 日志标签，用于输出日志信息
    public static final String TAG = "MainActivity";

    // 权限请求代码
    private static final int PERMISSION_REQUEST_CODE = 1;

    // 下载服务的绑定器，用于与下载服务进行交互
    private DownloadService.DownloadBinder downloadBinder;

    // 服务连接对象，用于绑定服务的回调
    private ServiceConnection connection = new ServiceConnection() {
        // 当服务连接成功时回调
        @Override
        public void onServiceConnected(ComponentName name, IBinder service) {
            // 将服务绑定器强制转换为DownloadBinder类型
            downloadBinder = (DownloadService.DownloadBinder) service;
        }

        // 当服务断开连接时回调
        @Override
        public void onServiceDisconnected(ComponentName name) {
            // 此处可添加断开连接后的处理逻辑
        }
    };

    // 活动创建时的回调方法
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        // 设置活动的布局文件
        setContentView(R.layout.activity_main);

        // 获取开始下载按钮，并设置点击监听器
        Button startDownload = (Button) findViewById(R.id.start_download);
        // 获取暂停下载按钮，并设置点击监听器
        Button pauseDownload = (Button) findViewById(R.id.pause_download);
        // 获取取消下载按钮，并设置点击监听器
        Button cancelDownload = (Button) findViewById(R.id.cancel_download);

        // 为按钮设置点击事件监听器
        startDownload.setOnClickListener(this);
        pauseDownload.setOnClickListener(this);
        cancelDownload.setOnClickListener(this);

        // 创建启动下载服务的意图
        Intent intent = new Intent(this, DownloadService.class);
        // 启动下载服务
        startService(intent);
        // 绑定服务，确保活动与服务能够交互
        bindService(intent, connection, BIND_AUTO_CREATE);

        // 检查应用是否具有写入外部存储的权限
        if (ContextCompat.checkSelfPermission(MainActivity.this, Manifest.permission.WRITE_EXTERNAL_STORAGE) != PackageManager.PERMISSION_GRANTED) {
            // 如果没有权限，请求权限
            ActivityCompat.requestPermissions(MainActivity.this, new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE}, 1);
        }
    }

    // 点击事件处理方法
    @Override
    public void onClick(View v) {
        // 如果downloadBinder为空，说明服务尚未绑定成功，直接返回
        if (downloadBinder == null) {
            return;
        }

        // 根据点击的按钮执行相应的操作
        if (v.getId() == R.id.start_download) {
            // 开始下载按钮被点击
            String url = "https://raw.githubusercontent.com/guolindev/eclipse/master/eclipse-inst-win64.exe";
            // 调用下载服务开始下载
            downloadBinder.startDownload(url);
        } else if (v.getId() == R.id.pause_download) {
            // 暂停下载按钮被点击
            downloadBinder.pauseDownload();
        } else if (v.getId() == R.id.cancel_download) {
            // 取消下载按钮被点击
            downloadBinder.cancelDownload();
        }
    }

    // 权限请求结果的回调方法
    @Override
    public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults, int deviceId) {
        // 根据请求码处理权限请求结果
        switch (requestCode) {
            case 1:
                // 如果用户拒绝了权限申请
                if (grantResults.length > 0 && grantResults[0] != PackageManager.PERMISSION_GRANTED) {
                    // 提示用户权限被拒绝
                    Toast.makeText(this, "拒绝权限将无法使用程序", Toast.LENGTH_SHORT).show();
                    // 退出活动
                    finish();
                }
                break;
            default:
                break;
        }
    }

    // 活动销毁时的回调方法
    @Override
    protected void onDestroy() {
        super.onDestroy();
        // 解除服务绑定，释放资源
        unbindService(connection);
    }
}
