    private void refreshFruits() {
        // 创建线程
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    // 等待1秒
                    Thread.sleep(999);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
                // 刷新UI
                runOnUiThread(new Runnable() {
                    @Override
                    public void run() {
                        // 初始化水果数据
                        initFruits();
                        // 通知适配器更新数据
                        adapter.notifyDataSetChanged();
                        // 停止SwipeRefreshLayout的刷新
                        swipeRefresh.setRefreshing(false);
                    }
                });
            }
        }).start();
    }

