int fa[N];
bool mark[N];
void init(int n)
{
	for(int i=1;i<=n;i++)fa[i]=i;
}
int find(int x)
{
	if(x==fa[x])return x;
	else{
		fa[x]=find(fa[x]);
		return fa[x];
	}
}
void unionn(int i,int j)
{
	int i_fa=find(i);
	int j_fa=find(j);
	fa[i_fa]=j_fa;
}
