```c++
#include<bits/stdc++.h>
#define IOS ios::sync_with_stdio(0), cin.tie(0), cout.tie(0)
using namespace std;
typedef long long ll;
const int N=2e5+10;
int a[N],h[N];
int main()
{
    IOS;
	int t,n,m;
	cin>>t;
	while(t--){
		cin>>n>>m;
		int ans=0,cnt=0;
		for(int i=0;i<n;i++){
			cin>>a[i];
		}
		for(int j=0;j<n;j++){
			cin>>h[j];
		}
		for(int i=0;i<n;i++){
			int j=i;
			while(j+1<n&&h[j]%h[j+1]==0)j++;
			int sum=0;
			for(int k=i,last=i;k<=j;k++){
				sum+=a[k];
				while(sum>m){
					sum-=a[last];
					last++;
				}
				ans=max(ans,k-last+1);
			}
			i=j;
	}
		cout<<ans<<endl;
	}
	return 0;
}
